import json,re
d=json.load(open('.claude.json',encoding='utf-8'))
def show(name,s):
    s=json.loads(json.dumps(s))
    env=s.get('env',{})
    for k in env: 
        if re.search('KEY|TOKEN|SECRET',k,re.I): env[k]='<redacted>'
    print(name, json.dumps(s))
for k,v in d.get('mcpServers',{}).items(): show('user:'+k,v)
for p,pv in d.get('projects',{}).items():
    for k,v in (pv.get('mcpServers') or {}).items():
        if 'plane' in k or 'devdesk' in k: show(p+':'+k,v)
"; ls ~/.claude/mcp*.json 2>/dev/null

